apiVersion: keda.sh/v1alpha1
kind: ScaledObject
metadata: {name: orders-consumer, namespace: workers}
spec:
  scaleTargetRef: {name: orders-consumer}
  minReplicaCount: 0
  maxReplicaCount: 50
  cooldownPeriod: 300
  fallback: {failureThreshold: 3, replicas: 5}
  triggers:
  - type: aws-sqs-queue
    authenticationRef: {name: aws-irsa}
    metadata: {queueURL: https://sqs.eu-west-1.amazonaws.com/123/orders, queueLength: "100", awsRegion: eu-west-1}
